      "causa_raiz": "Concatenação excessiva de strings dentro do Update (s += i.ToString()) e alocação desnecessária de arrays (new object[10000]) a cada frame, gerando mais de 10 MB de lixo por frame e disparando pausas de Garbage Collector de 16 ms.",
      "codigo_refatorado": "using System.Text;
using UnityEngine;

namespace PerformanceAdvisor.StressTest
{
    public class StressTestScene : MonoBehaviour
    {
        public bool stressGc = false;
        public bool stressCpu = false;
        public bool stressDraw = false;
        public GameObject testPrefab;
        [Range(1, 20)] public float spawnRadius = 10f;
        [Range(1, 50)] public int cubesPerFrame = 1;
        public bool useUniqueMaterials = false;
        [Range(1, 512)] public int cpuScansPerFrame = 1;
        public int emptyObjects = 0;
        public int gcConcatIterations = 1000;
        public int gcArrayAllocs = 0;
        public int overdrawLayers = 0;
        public Material overdrawMaterial;
        [Range(0, 2000)] public int prepopulateCount = 0;

        private StringBuilder sbCached;
        private MaterialPropertyBlock propertyBlock;
        private static readonly int ColorPropertyId = Shader.PropertyToID("_Color");

        private void Awake()
        {
            sbCached = new StringBuilder(gcConcatIterations * 8);
            propertyBlock = new MaterialPropertyBlock();
        }

        private void Start()
        {
            if (prepopulateCount > 0 && testPrefab != null)
            {
                for (int i = 0; i < prepopulateCount; i++)
                {
                    SpawnOne();
                }
            }
            for (int i = 0; i < emptyObjects; i++)
            {
                new GameObject("Empty_" + i);
            }
            if (overdrawLayers > 0 && overdrawMaterial != null)
            {
                BuildOverdrawLayers();
            }
        }

        private void BuildOverdrawLayers()
        {
            Camera cam = Camera.main;
            if (cam == null) return;
            float halfFov = cam.fieldOfView * 0.5f * Mathf.Deg2Rad;
            for (int i = 0; i < overdrawLayers; i++)
            {
                float d = cam.nearClipPlane + 0.05f + i * 0.001f;
                float h = 2f * d * Mathf.Tan(halfFov) * 1.1f;
                var quad = GameObject.CreatePrimitive(PrimitiveType.Quad);
                Destroy(quad.GetComponent<Collider>());
                quad.name = "Overdraw_" + i;
                quad.transform.SetParent(cam.transform, false);
                quad.transform.localPosition = new Vector3(0f, 0f, d);
                quad.transform.localScale = new Vector3(h * cam.aspect, h, 1f);
                quad.GetComponent<Renderer>().sharedMaterial = overdrawMaterial;
            }
        }

        private void Update()
        {
            if (stressGc)
            {
                sbCached.Clear();
                for (int i = 0; i < gcConcatIterations; i++)
                {
                    sbCached.Append(i);
                }
            }

            if (stressDraw && testPrefab != null)
            {
                int n = Mathf.Max(1, cubesPerFrame);
                for (int i = 0; i < n; i++)
                {
                    SpawnOne();
                }
            }
        }

        private void SpawnOne()
        {
            var clone = Instantiate(
                testPrefab,
                UnityEngine.Random.insideUnitSphere * spawnRadius,
                Quaternion.identity);

            if (useUniqueMaterials)
            {
                var rend = clone.GetComponent<Renderer>();
                if (rend != null)
                {
                    propertyBlock.SetColor(ColorPropertyId, UnityEngine.Random.ColorHSV());
                    rend.SetPropertyBlock(propertyBlock);
                }
            }
        }
    }
}",
      "explicacao_didatica": "Strings em C# são imutáveis; concatenar strings com '+' cria um texto novo e descarta o anterior toda vez, acumulando gigabytes de lixo na memória. O Garbage Collector precisa congelar seu jogo para limpar essa sujeira. Usar StringBuilder reaproveita o mesmo espaço na memória sem criar cópias. Além disso, trocar renderer.material por MaterialPropertyBlock impede a Unity de criar duplicatas ocultas de materiais na memória."
    },
    {
      "tipo": "CPU",
      "causa_raiz": "Chamada repetitiva a GameObject.FindObjectsOfType no método Update(). Esta função varre toda a hierarquia interna da cena na memória nativa em C++, custando até 55 ms de processamento a cada frame.",
      "codigo_refatorado": "// Remova buscas em massa do loop Update.
// Caso precise iterar objetos, registre-os em uma lista na criação (Awake/OnEnable) e desregistre na destruição (OnDisable).
// Exemplo de padrão de registro eficiente:
public static class ActorRegistry
{
    public static readonly System.Collections.Generic.List<GameObject> ActiveActors = new System.Collections.Generic.List<GameObject>();
}",
      "explicacao_didatica": "Procurar objetos na cena durante o Update é como ler uma lista telefônica inteira do início ao fim 60 vezes por segundo para achar um amigo. A melhor prática é manter uma lista estática onde os próprios objetos se inscrevem ao 'nascer' (Awake) e saem ao serem destruídos (OnDisable), eliminando a necessidade de varredura e liberando a CPU."
    }
  ],
  "dicas_level_design": null
}

